package com.myassist.customer.ui;
import android.content.Intent; import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.myassist.customer.MyAssistApp; import com.myassist.customer.network.*; import org.json.JSONObject;
public class LoginActivity extends AppCompatActivity { EditText phone,pass; TextView error; ProgressBar progress; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_login);phone=findViewById(R.id.etPhone);pass=findViewById(R.id.etPass);error=findViewById(R.id.tvError);progress=findViewById(R.id.progress);findViewById(R.id.btnLogin).setOnClickListener(v->login());findViewById(R.id.tvGoRegister).setOnClickListener(v->startActivity(new Intent(this,RegisterActivity.class)));} void login(){progress.setVisibility(View.VISIBLE);String p=phone.getText().toString().trim(),pw=pass.getText().toString();RequestBuilderHelper.login(p,pw,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject o){MyAssistApp.session().save(o.optString("access_token"),o.optInt("user_id"),o.optString("role"),o.optString("full_name"));runOnUiThread(()->{startActivity(new Intent(LoginActivity.this,HomeActivity.class));finish();});}public void onError(ApiClient.ApiException e){runOnUiThread(()->{progress.setVisibility(View.GONE);error.setText(e.userMessage);error.setVisibility(View.VISIBLE);});}});} static class RequestBuilderHelper { static void login(String p,String pw,ApiService.Callback<JSONObject> cb){ApiService.run(ApiService.get("api/v1/auth/login?phone="+android.net.Uri.encode(p)+"&password="+android.net.Uri.encode(pw)),x->x,cb);} } }